 const downloadPdfBtn=document.getElementById('downloadPdfBtn');
 if(downloadPdfBtn) downloadPdfBtn.addEventListener('click',async()=>{if(downloadMenu)downloadMenu.classList.add('hidden');await downloadPDF(state.editing);});
 const downloadJpgBtn=document.getElementById('downloadJpgBtn');
 if(downloadJpgBtn) downloadJpgBtn.addEventListener('click',async()=>{if(downloadMenu)downloadMenu.classList.add('hidden');await downloadDocumentImages(state.editing);});
