async function downloadDocumentImages(d){
  if(!d){toast('No hay documento para descargar.');return false}
  try{
    if(!window.html2canvas)throw new Error('CAPTURADOR_NO_DISPONIBLE');

    let paper=document.getElementById('paper'),temporary=false;
    if(!paper){
      paper=document.createElement('div');
      paper.innerHTML=docHTML(d);
      paper.style.cssText='position:absolute;left:0;top:0;width:794px;min-height:1123px;background:#fff;padding:0;font-family:Arial;color:#111;visibility:visible;opacity:1;pointer-events:none;z-index:2147483646';
      document.body.appendChild(paper);temporary=true;
    }

    try{
      const target=paper.matches('.preview-paper')
        ? (paper.querySelector(':scope > .preview-paper')||paper)
        : (paper.querySelector('.preview-paper')||paper);

      for(const img of [...target.querySelectorAll('img')]){
        try{
          if(!img.complete)await new Promise(resolve=>{img.onload=img.onerror=resolve});
          if(img.naturalWidth>0 && !String(img.src).startsWith('data:')){
            const cv=document.createElement('canvas');
            cv.width=img.naturalWidth;cv.height=img.naturalHeight;
            cv.getContext('2d').drawImage(img,0,0);
            img.src=cv.toDataURL('image/png');
          }
        }catch(e){}
      }

      if(document.fonts?.ready)await document.fonts.ready;
      await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));

      // Compacta únicamente la salida PDF para que la nota no empuje
    // los datos bancarios y totales fuera del área visible. La vista
    // normal de la aplicación conserva exactamente su diseño actual.
    target.classList.add('pdf-compact');

    const rect=target.getBoundingClientRect();
      const width=Math.max(1,Math.ceil(target.scrollWidth||rect.width||794));
      const height=Math.max(1,Math.ceil(target.scrollHeight||rect.height||1123));

      const canvas=await window.html2canvas(target,{
        width,height,scale:1.75,
        backgroundColor:'#fff',
        useCORS:false,allowTaint:false,
        imageTimeout:20000,logging:false,
        foreignObjectRendering:false,
        scrollX:0,scrollY:0,x:0,y:0
      });

      if(!canvas?.width||!canvas?.height)throw new Error('Imagen del documento vacía');

      const data=canvas.toDataURL('image/jpeg',0.90);
      if(!data||data.length<1000)throw new Error('JPG inválido');

      const safe=String(d.folio||'documento').replace(/[\\/:*?"<>|]/g,'_');
      const a=document.createElement('a');
      a.href=data;
      a.download=`${safe}_SK_House_Construction.jpg`;
      a.style.display='none';
      document.body.appendChild(a);
      a.click();
      setTimeout(()=>a.remove(),1000);
      toast('Cotización descargada en JPG.');
      return true;
    }finally{
      if(temporary)paper.remove();
    }
  }catch(e){
    console.error('Error generando JPG:',e);
    toast('No se pudo generar la cotización en JPG.');
    return false;
  }
}
