(function(){
  const norm=v=>String(v??'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const escSafe=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
  const key=x=>String(x?.id||'');
  function records(){
    const docs=Array.isArray(state.documents)?state.documents:[];
    const clients=Array.isArray(state.clients)?state.clients:[];
    const products=Array.isArray(state.products)?state.products:[];
    const tools=Array.isArray(state.toolLists)?state.toolLists:[];
    return [
      ...docs.map(x=>({kind:x.type==='quote'?'Cotización':'Nota de venta',id:key(x),name:x.folio||'Documento',text:[x.folio,x.client?.name,x.client?.phone,x.client?.email,x.client?.rfc,x.date,x.notes,(x.items||[]).map(i=>[i.desc,i.name,i.obs].join(' ')).join(' ')].join(' '),value:x})),
      ...clients.map((x,i)=>({kind:'Cliente',id:key(x)||`client-${i}`,name:x.name||'Cliente',text:[x.name,x.phone,x.email,x.rfc,x.address].join(' '),value:x,index:i})),
      ...products.map((x,i)=>({kind:'Producto',id:key(x)||`product-${i}`,name:x.name||x.description||'Producto',text:[x.name,x.description,x.price,x.unit].join(' '),value:x,index:i})),
      ...tools.map((x,i)=>({kind:'Lista de herramientas',id:key(x)||`tool-${i}`,name:x.name||'Lista',text:[x.name,x.date,x.notes,(x.items||[]).map(i=>[i.name,i.unit].join(' ')).join(' ')].join(' '),value:x,index:i}))
    ];
  }
  function renderGlobalSearch(q){
    const box=document.getElementById('globalSearchResults'); if(!box)return;
    const query=norm(q);
    if(!query){box.innerHTML='';box.classList.remove('open');return;}
    const hits=records().filter(r=>norm(r.text).includes(query)).slice(0,30);
    box.innerHTML=hits.length?hits.map(r=>`<button type="button" class="search-hit" data-search-kind="${escSafe(r.kind)}" data-search-id="${escSafe(r.id)}" data-search-index="${r.index??''}">
      <span class="search-type">${escSafe(r.kind)}</span><span class="search-name">${escSafe(r.name)}</span>
    </button>`).join(''):'<div class="search-empty">No se encontraron resultados.</div>';
    box.classList.add('open');
  }
  function openHit(el){
    const kind=el.dataset.searchKind, id=el.dataset.searchId, idx=el.dataset.searchIndex;
    const r=records().find(x=>x.kind===kind && (String(x.id)===String(id) || (x.index!==undefined&&String(x.index)===String(idx))));
    if(!r)return toast('No se encontró ese registro.');
    document.getElementById('globalSearchResults')?.classList.remove('open');
    if(kind==='Cotización'||kind==='Nota de venta'){editDoc(r.value.id);return;}
    if(kind==='Cliente'){
      newDocument('quote');
      state.editing.client={name:r.value.name||'',phone:r.value.phone||'',email:r.value.email||'',rfc:r.value.rfc||'',address:r.value.address||''};
      render();
      toast('Cliente cargado en el documento. Puedes editar sus datos.');
      return;
    }
    if(kind==='Producto'){
      state.view='products';window._editingProductIndex=r.index!==undefined?r.index:state.products.indexOf(r.value);render();
      setTimeout(()=>{
        const p=r.value;
        const n=document.getElementById('productName'),d=document.getElementById('productDescription'),pr=document.getElementById('productPrice'),u=document.getElementById('productUnit');
        if(n)n.value=p.name||'';if(d)d.value=p.description||'';if(pr)pr.value=p.price??0;if(u)u.value=p.unit||'';
        const pi=document.getElementById('productImageInput'),pv=document.getElementById('productImagePreview');
        if(pi)pi.value='';if(pv)pv.innerHTML=p.image?`<img src="${p.image}" alt="Imagen del producto">`:'';
      },0);
      toast('Producto cargado. Puedes editarlo.');
      return;
    }
    if(kind==='Lista de herramientas'){const ti=r.index!==undefined?r.index:state.toolLists.indexOf(r.value);const item=state.toolLists[ti];if(item){state.toolEditing=JSON.parse(JSON.stringify(item));toolEditor();}return;}
  }
  document.addEventListener('input',e=>{if(e.target?.id==='globalSearch')renderGlobalSearch(e.target.value);});
  document.addEventListener('click',e=>{
    const hit=e.target.closest?.('.search-hit'); if(hit){openHit(hit);return;}
    const box=document.getElementById('globalSearchResults'); if(box&&!e.target.closest('.global-search'))box.classList.remove('open');
  });
  window.SKCatalog={
    clients:()=>Array.isArray(state.clients)?state.clients:[],
    products:()=>Array.isArray(state.products)?state.products:[],
    applyProduct:function(product,i){
      if(!state.editing?.items?.[i])return;
      const line=state.editing.items[i];
      line.desc=product.name||product.description||product.descripcion||'';
      const p=Number(product.price??product.precio??product.unitPrice);
      if(Number.isFinite(p))line.price=p;
      if(product.unit||product.unidad)line.unit=product.unit||product.unidad;
      if(product.image&&!line.images?.length)line.images=[{data:product.image,text:'',scale:1}];
      if(Array.isArray(product.images)&&!line.images?.length)line.images=JSON.parse(JSON.stringify(product.images));
      renderItems();updateTotalsUI();
    }
  };
})();
