(function(){
  function readProductImage(cb){
    const input=document.getElementById('productImageInput');
    if(!input || !input.files || !input.files[0]) return cb(null);
    const r=new FileReader();
    r.onload=()=>cb(r.result);
    r.onerror=()=>cb(null);
    r.readAsDataURL(input.files[0]);
  }
  document.addEventListener('change',e=>{
    if(e.target?.id==='productImageInput'){
      const f=e.target.files?.[0], box=document.getElementById('productImagePreview');
      if(!box)return;
      if(!f){box.innerHTML='';return;}
      const r=new FileReader();
      r.onload=()=>box.innerHTML=`<img src="${r.result}" alt="Vista previa del producto">`;
      r.readAsDataURL(f);
    }
  });
  window.SKProductImage={read:readProductImage};
})();

